<?php
require_once __DIR__.'/../app/helpers.php';require_auth();require_once __DIR__.'/../app/Services/NotificationService.php';$svc=new NotificationService(Database::connection());$uid=(int)auth_user()['id'];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(isset($_POST['all']))$svc->markAllRead($uid);elseif(isset($_POST['id']))$svc->markRead($uid,(int)$_POST['id']);redirect('/commserve/public/notifications.php');}$items=$svc->unread($uid,100);?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Notifications</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body><div class="container py-4"><div class="d-flex justify-content-between align-items-center mb-4"><h2>Notifications</h2><form method="post"><?=csrf_field()?><button name="all" value="1" class="btn btn-outline-primary">Mark all as read</button></form></div><?php if(!$items):?><div class="alert alert-light border">You're all caught up.</div><?php endif;?><?php foreach($items as $n):?><div class="card mb-3 shadow-sm border-0"><div class="card-body"><div class="d-flex justify-content-between"><div><h5><?=e($n['title'])?></h5><p class="mb-1"><?=e($n['message'])?></p><small class="text-muted"><?=e($n['created_at'])?> · <?=e($n['channel'])?></small></div><form method="post"><?=csrf_field()?><input type="hidden" name="id" value="<?=$n['id']?>"><button class="btn btn-sm btn-outline-secondary">Mark read</button></form></div></div></div><?php endforeach;?><a href="/commserve/public/dashboard.php" class="btn btn-link">Back to dashboard</a></div></body></html>
